using UnityEngine;

namespace CoreAI.Demos.BlockWorld
{
    /// <summary>
    /// The spawn area baked by the scene builder, so the scene shows the world while it is open in the Editor. At
    /// Play the real world is generated by the Block World mods, so the preview removes itself before anything is
    /// drawn; it is tagged EditorOnly, so a built player never carries it.
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class BlockWorldEditorPreview : MonoBehaviour
    {
        private void Awake()
        {
            if (!Application.isPlaying)
            {
                return;
            }

            gameObject.SetActive(false);
            Destroy(gameObject);
        }
    }
}
